WHERE 1 = 1
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR c.description LIKE CONCAT('%', #{keyword}, '%') OR owner_user.username LIKE CONCAT('%', #{keyword}, '%') OR owner_profile.nickname LIKE CONCAT('%', #{keyword}, '%'))
AND c.status = #{status}

mapper.select:
SELECT COUNT(*)
FROM circles
WHERE id = #{id}

SELECT COUNT(*)
FROM circle_members
WHERE circle_id = #{circleId}
  AND user_id = #{userId}

mapper.delete:
